# weighted mean of daily units with weights decay^(days from fit end), grid variants
def curve(sku, grid, alphas):
    s = fit[fit['sku']==sku]
    u = s.groupby(s['placed_at'].dt.normalize())['units'].sum()
    if grid=='act': g=pd.date_range(u.index.min(), u.index.max())
    elif grid=='to_end': g=pd.date_range(u.index.min(), end)
    else: g=pd.date_range(lo.normalize(), end)
    f=u.reindex(g,fill_value=0).values.astype(float)
    n=len(f)
    ages = np.arange(n-1,-1,-1)  # days before end
    out=[]
    for a in alphas:
        w=(1-a)**ages
        out.append((w*f).sum()/w.sum())
    return np.array(out)
