import numpy as np
import pandas as pd


def sku_trade_days(fit_df):
    return fit_df.groupby("sku")["placed_at"].apply(
        lambda ts: float(ts.dt.normalize().nunique()))


def account_gap(fit_df):
    known = fit_df.dropna(subset=["account_id"])

    def mean_gap(ts):
        days = np.sort(ts.dt.normalize().unique())
        if len(days) < 2:
            return np.nan
        return float(np.diff(days).astype("timedelta64[D]").astype("float64").mean())

    gaps = known.groupby("account_id")["placed_at"].apply(mean_gap)
    portfolio = float(gaps.mean())
    return gaps, portfolio


def add(df, trade_days, gaps, portfolio_gap):
    out = df.copy()
    td = trade_days.reindex(out["sku"]).values
    out["f_sku_trade_days"] = np.where(np.isnan(td), 0.0, td)
    gv = gaps.reindex(out["account_id"]).values
    out["f_account_order_gap"] = np.where(np.isnan(gv), portfolio_gap, gv)
    return out
