import numpy as np
import pandas as pd


class RateEncoder(object):

    def __init__(self, column, smoothing):
        self.column = column
        self.smoothing = float(smoothing)
        self.rates_ = None
        self.prior_ = None

    def fit(self, df, label):
        prior = float(df[label].mean())
        grp = df.groupby(self.column)[label].agg(["sum", "size"])
        self.rates_ = ((grp["sum"] + self.smoothing * prior)
                       / (grp["size"] + self.smoothing)).astype("float64")
        self.prior_ = prior
        return self

    def transform(self, df):
        values = self.rates_.reindex(df[self.column]).values
        return np.where(np.isnan(values), self.prior_, values)


def fit_all(fit_df, columns, smoothing, label):
    return {column: RateEncoder(column, smoothing).fit(fit_df, label)
            for column in columns}


def apply_all(df, encoders):
    out = df.copy()
    for column, enc in encoders.items():
        out["f_rate_%s" % column] = enc.transform(out)
    return out
